mapper.sql:
WHERE type = 1
AND LOCATE(#{q.data}, data) > 0

  AND (dataset_id IS NULL OR dataset_id = 0)
  AND dataset_id = #{q.datasetId}

AND product_time >= #{q.beginProductTime}
AND product_time <= #{q.endProductTime}
AND LOCATE(#{q.productModel}, product_model) > 0
AND LOCATE(#{q.productBatch}, product_batch) > 0
AND LOCATE(#{q.processNum}, process_num) > 0

mapper.select:
SELECT  FROM biz_data_collection 
AND id IN #{id}
ORDER BY id
